import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { BufferSink, ChecksumFlag, Decoder, Encoder } from '../../src/ltx/index.ts';
import type { Header } from '../../src/ltx/index.ts';
import { checksumPage } from '../../src/ltx/checksum.ts';
import { byteEq } from '../helpers/byte.ts';

/**
 * Golden interop against Go's `superfly/ltx` writer.
 *
 * The `.ltx` fixtures in `testdata/go/` are generated by
 * `tools/golden/main.go` (see the `interop-go` CI job). They prove that our
 * TypeScript decoder reads files produced by the canonical Go LTX
 * implementation — the header, page frames, page index and trailer must all
 * round-trip, the LZ4 **block** decompression must undo Go's bytes, and the
 * CRC-64 (ISO) page/file checksums must agree.
 *
 * Our `compressBlock` is a byte-identical TypeScript port of Go's
 * `pierrec/lz4/v4` Fast block compressor, so this verifies **both** directions:
 * decoding Go files, and re-encoding the same logical content to byte-identical
 * output. As long as the fixtures are regenerated by `tools/golden`, drift in
 * Go's format, our decoder or our encoder is caught here.
 */

const dir = fileURLToPath(new URL('../../testdata/go/', import.meta.url));

function makePage(seed: number): Uint8Array {
  const b = new Uint8Array(512);
  for (let i = 0; i < 512; i++) b[i] = (seed + (i % 7)) & 0xff;
  return b;
}

/** Rolling post-apply checksum our decoder derives from a snapshot's pages. */
function snapshotPostApply(commit: number): bigint {
  let chk = ChecksumFlag;
  for (let pgno = 1; pgno <= commit; pgno++) {
    chk = ChecksumFlag | (chk ^ checksumPage(pgno, makePage(pgno)));
  }
  return chk;
}

test('go interop: decodes a Go-produced sparse non-snapshot LTX file', async () => {
  const buf = await readFile(`${dir}sparse-non-snapshot.ltx`);
  const dec = new Decoder(new Uint8Array(buf));
  dec.decodeHeader();

  const h = dec.Header();
  assert.equal(h.version, 3);
  assert.equal(h.pageSize, 512);
  assert.equal(h.commit, 16);
  assert.equal(h.minTXID, 2n);
  assert.equal(h.maxTXID, 3n);
  assert.equal(h.timestamp, 1000n);
  assert.equal(h.preApplyChecksum, ChecksumFlag | 1n);

  const data = new Uint8Array(512);
  const seen: number[] = [];
  for (;;) {
    const ph = dec.decodePage(data);
    if (ph === null) break;
    seen.push(ph.pgno);
    assert.ok(byteEq(data, makePage(ph.pgno)), `page ${ph.pgno} content`);
  }
  assert.deepEqual(seen, [2, 5, 9, 16]);

  // close() recomputes and validates the file checksum against Go's trailer.
  dec.close();
});

test('go interop: verifies a Go-produced snapshot LTX file (post-apply + file checksum)', async () => {
  const buf = await readFile(`${dir}snapshot.ltx`);
  const dec = new Decoder(new Uint8Array(buf));
  // verify() recomputes the file checksum AND the post-apply checksum, asserting
  // both against the trailer written by Go.
  dec.verify();
  assert.equal(dec.Header().commit, 6);
  assert.equal(dec.Header().minTXID, 1n);
  // The trailer's post-apply checksum (computed by Go) matches our checksum scheme.
  assert.equal(dec.Trailer().postApplyChecksum, snapshotPostApply(6));
});

/** Re-encode the same logical content as `tools/golden` using our encoder. */
function encode(pgnos: number[], hdr: Omit<Header, 'version' | 'flags' | 'pageSize'>, postApply: bigint): Uint8Array {
  const sink = new BufferSink();
  const enc = new Encoder(sink);
  enc.encodeHeader({ version: 3, flags: 0, pageSize: 512, ...hdr });
  for (const pgno of pgnos) enc.encodePage({ pgno, flags: 0 }, makePage(pgno));
  enc.setPostApplyChecksum(postApply);
  enc.close();
  return sink.toBuffer();
}

function rollingPostApply(pgnos: number[]): bigint {
  let chk = ChecksumFlag;
  for (const pgno of pgnos) chk = ChecksumFlag | (chk ^ checksumPage(pgno, makePage(pgno)));
  return chk;
}

test('go interop: sparse non-snapshot encodes to byte-identical Go output', async () => {
  const want = await readFile(`${dir}sparse-non-snapshot.ltx`);
  const got = encode([2, 5, 9, 16], {
    commit: 16, minTXID: 2n, maxTXID: 3n, timestamp: 1000n,
    preApplyChecksum: ChecksumFlag | 1n, walOffset: 0n, walSize: 0n,
    walSalt1: 0, walSalt2: 0, nodeID: 0n,
  }, rollingPostApply([2, 5, 9, 16]));
  assert.ok(byteEq(got, want), 'sparse non-snapshot LTX bytes must match Go exactly');
});

test('go interop: snapshot encodes to byte-identical Go output', async () => {
  const want = await readFile(`${dir}snapshot.ltx`);
  const got = encode([1, 2, 3, 4, 5, 6], {
    commit: 6, minTXID: 1n, maxTXID: 4n, timestamp: 1000n,
    preApplyChecksum: 0n, walOffset: 0n, walSize: 0n,
    walSalt1: 0, walSalt2: 0, nodeID: 0n,
  }, rollingPostApply([1, 2, 3, 4, 5, 6]));
  assert.ok(byteEq(got, want), 'snapshot LTX bytes must match Go exactly');
});
